import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, EmptyState, Icon, StatusPill } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { nextRuns, routines } from "./data.js";

function Toast({message}){return message&&html`<div class="p-routines-toast" role="status">${message}</div>`}
function Head({action}){return html`<header class="p-routines-head"><div><p>AUTOMATION CONTROL</p><h1>Build routines</h1><span>Start the right conversation when a signal arrives.</span></div><button class="p-routines-primary" onClick=${action}><${Icon} name="plus"/>New routine</button></header>`}
function Spark({runs}){return html`<span class="p-routines-spark" aria-label="Recent run history">${runs.map(run=>html`<i class=${run}></i>`)}</span>`}
function RoutineDialog({close,notify}){const [name,setName]=useState('');return html`<${Dialog} onClose=${close}><div class="p-routines-dialog"><p>NEW ROUTINE</p><h2>Name the automation</h2><label>Routine name<input autoFocus value=${name} onInput=${e=>setName(e.target.value)} placeholder="e.g. Review new pull requests"/></label><label>Trigger<select><option>Schedule</option><option>GitHub event</option><option>Webhook</option><option>Manual</option></select></label><div><button onClick=${close}>Cancel</button><button class="p-routines-primary" disabled=${!name.trim()} onClick=${()=>{close();notify('Routine draft created')}}>Create draft</button></div></div></${Dialog}>`}
function Builder({routine,notify,compact=false}){return html`<section class=${compact?'p-routines-builder compact':'p-routines-builder'}><header><div><p>ROUTINE BUILDER</p><h2>${compact?'Automation details':'When this happens, start this conversation'}</h2></div><${StatusPill} status=${routine.state==='paused'?'held':'running'}/></header><div class="p-routines-sentence"><span>When</span><button>${routine.trigger}<${Icon} name="chevron-down"/></button><span>then</span><button>${routine.agent}<${Icon} name="chevron-down"/></button><span>does</span><button>${routine.name}<${Icon} name="chevron-down"/></button></div><div class="p-routines-builder-grid"><label>Prompt template<textarea value=${routine.prompt} readOnly></textarea></label><div class="p-routines-fields"><label>Target<select value=${routine.project}><option>${routine.project}</option></select></label><label>Budget cap<input value=${routine.budget} readOnly/></label><label>Approval<select><option>${routine.approval}</option></select></label></div></div>${routine.cron!=='event'&&routine.cron!=='manual'&&html`<div class="p-routines-cron"><b>${routine.human}</b><code>${routine.cron}</code><span>Human-readable cron · local operator time</span><ol>${nextRuns.map(run=>html`<li>${run}</li>`)}</ol></div>`}<footer><button onClick=${()=>notify('Dry run queued — no conversation will start')}>Dry run</button><button class="p-routines-primary" onClick=${()=>notify('Routine changes saved')}>Save routine</button></footer></section>`}
function ListVariant({notify,newRoutine}){const [selected,setSelected]=useState(routines[0]);return html`<main class="e-page p-routines-page"><${Head} action=${newRoutine}/><div class="p-routines-list-layout"><section class="p-routines-list"><header><b>5 routines</b><span>Enabled and paused automations</span></header>${routines.map(r=>html`<button class=${selected.id===r.id?'selected':''} onClick=${()=>setSelected(r)}><span class=${`p-routines-state ${r.state}`}></span><div><b>${r.name}</b><small>${r.trigger} · ${r.human}</small></div><span class="p-routines-next">${r.next}</span><${Spark} runs=${r.runs}/><${StatusPill} status=${r.state==='paused'?'held':'running'}/></button>`)}</section><${Builder} routine=${selected} notify=${notify}/></div></main>`}
function ScheduleVariant({notify,newRoutine}){const [selected,setSelected]=useState(routines[0]);const days=['Mon 28','Tue 29','Wed 30','Thu 31','Fri 1'];const slots=[['09:00',routines[0],0],['11:30',routines[1],2],['14:00',routines[2],3],['16:00',routines[3],1]];return html`<main class="e-page p-routines-page"><${Head} action=${newRoutine}/><section class="p-routines-calendar"><header><div><p>UPCOMING AUTOMATIONS</p><h2>Week of October 28</h2></div><span>Local operator time · 4 scheduled conversations</span></header><div class="p-routines-week"><aside>${slots.map(s=>html`<time>${s[0]}</time>`)}</aside><div class="p-routines-days">${days.map(day=>html`<b>${day}</b>`)}${slots.map(([time,routine,column])=>html`<button class=${`p-routine-event col-${column}`} onClick=${()=>setSelected(routine)}><small>${time}</small><strong>${routine.name}</strong><span>${routine.agent} · ${routine.project}</span></button>`)}</div></div></section><div class="p-routines-drawer"><${Builder} routine=${selected} notify=${notify} compact=${true}/></div></main>`}
function BoardVariant({notify,newRoutine}){const [selected,setSelected]=useState(routines[1]);const types=['GitHub','Schedule','Webhook','Manual'];return html`<main class="e-page p-routines-page"><${Head} action=${newRoutine}/><div class="p-routines-board-layout"><section class="p-routines-board">${types.map(type=>{const items=routines.filter(r=>r.type===type);return html`<section><header><b>${type}</b><span>${items.length}</span></header>${items.length?items.map(r=>html`<button class=${selected.id===r.id?'selected':''} onClick=${()=>setSelected(r)}><div><${StatusPill} status=${r.state==='paused'?'held':'running'}/><${Spark} runs=${r.runs}/></div><b>${r.name}</b><small>${r.next} · ${r.agent}</small></button>`):html`<${EmptyState}>No ${type.toLowerCase()} routines</${EmptyState}>`}</section>`})}</section><aside class="p-routines-detail"><p>ROUTINE DETAIL</p><h2>${selected.name}</h2><span>${selected.trigger} · ${selected.project}</span><div class="p-routines-failure ${selected.runs.includes('fail')?'show':''}"><b>${selected.runs.includes('fail')?'Failure handling':'Healthy delivery'}</b><p>${selected.runs.includes('fail')?'Retry once after 10 minutes, then pause and notify the operator.':'Last five runs completed without a recovery action.'}</p></div><h3>Last runs</h3><ul>${selected.runs.map((run,i)=>html`<li><i class=${run}></i>${i===0?selected.last:`${i+1}d ago · ${run==='fail'?'failed and recovered':'conversation completed'}`}</li>`)}</ul><button onClick=${()=>notify('Dry run preview opened — no agent started')}>Preview dry run</button><div class="p-routines-detail-actions"><button onClick=${()=>notify(selected.state==='paused'?'Routine resumed':'Routine paused')}>${selected.state==='paused'?'Resume':'Pause'}</button><button class="p-routines-primary" onClick=${()=>notify('Conversation started from this routine')}>Run now</button></div></aside></div></main>`}
export default function RoutinesPage(){const [toast,setToast]=useState('');const [dialog,setDialog]=useState(false);const notify=message=>{setToast(message);setTimeout(()=>setToast(''),2600)};return html`<${PageVariants} variants=${[{key:'1',name:'Builder list',render:()=>html`<${ListVariant} notify=${notify} newRoutine=${()=>setDialog(true)}/>`},{key:'2',name:'Schedule',render:()=>html`<${ScheduleVariant} notify=${notify} newRoutine=${()=>setDialog(true)}/>`},{key:'3',name:'Trigger board',render:()=>html`<${BoardVariant} notify=${notify} newRoutine=${()=>setDialog(true)}/>`}]}/>${dialog&&html`<${RoutineDialog} close=${()=>setDialog(false)} notify=${notify}/>`}<${Toast} message=${toast}/>`}
